  "rivers.bod_title":      { en: "BOD  - Biochemical Oxygen Demand", ta: "BOD  - உயிர்வேதியியல் ஆக்சிஜன் தேவை" },
  "rivers.bod_desc":       { en: "Organic pollution load. A clean river has < 2 mg/L. Above 30 mg/L indicates severe sewage contamination.", ta: "கரிம மாசு சுமை. சுத்தமான ஆற்றில் < 2 mg/L. 30 mg/L-க்கு மேல் என்றால் கடுமையான கழிவு மாசு." },
  "rivers.cod_title":      { en: "COD - Chemical Oxygen Demand", ta: "COD - வேதியியல் ஆக்சிஜன் தேவை" },
  "rivers.cod_desc":       { en: "Total chemical pollution. COD >> BOD indicates industrial discharge, not just sewage.", ta: "மொத்த வேதி மாசு. COD >> BOD என்றால் தொழிற்சாலை வெளியேற்றம், வெறும் கழிவு அல்ல." },
  "rivers.fc_title":       { en: "Fecal Coliform", ta: "மலக் கொலிஃபார்ம்" },
  "rivers.fc_desc":        { en: "Sewage bacteria count. Bathing standard is < 500 MPN/100ml. Values above 10,000 indicate raw sewage.", ta: "கழிவுநீர் பாக்டீரியா எண்ணிக்கை. குளியல் தரம் < 500 MPN/100ml. 10,000-க்கு மேல் என்றால் சுத்திகரிக்கப்படாத கழிவுநீர்." },
  "rivers.tds_title":      { en: "TDS - Total Dissolved Solids", ta: "TDS - மொத்த கரைந்த திடப்பொருள்" },
  "rivers.tds_desc":       { en: "Overall mineral/salt content. Drinking water limit is 500 mg/L. High TDS makes water unusable.", ta: "மொத்த கனிம/உப்பு உள்ளடக்கம். குடிநீர் வரம்பு 500 mg/L. அதிக TDS நீரை பயனற்றதாக்கும்." },
  "rivers.nitrate_title":  { en: "Nitrate", ta: "நைட்ரேட்" },
  "rivers.nitrate_desc":   { en: "From sewage and fertilizer runoff. Above 45 mg/L is unsafe for drinking. Can contaminate nearby groundwater.", ta: "கழிவுநீர் மற்றும் உர வழிப்பாய்வு. 45 mg/L-க்கு மேல் குடிப்பதற்கு பாதுகாப்பற்றது. அருகிலுள்ள நிலத்தடி நீரை மாசுபடுத்தலாம்." },
  "rivers.metals_title":   { en: "Heavy Metals", ta: "கனரக உலோகங்கள்" },
  "rivers.metals_desc":    { en: "Chromium, Lead, Cadmium from industrial discharge. Toxic even at trace levels. Accumulates in fish and sediment.", ta: "தொழிற்சாலை வெளியேற்றத்தின் குரோமியம், ஈயம், காட்மியம். சிறிய அளவிலும் நச்சு. மீன் மற்றும் வண்டலில் குவிகிறது." },
